async function _showStatus(cwd, options) {
  const { detectClaudeCode, detectCodex } =
    await import("../lib/claude-code-bridge.js");
  const claude = detectClaudeCode();
  const codex = detectCodex();

  const status = {
    cliTools: {
      claude: claude.found ? claude.version : "not found",
      codex: codex.found ? codex.version : "not found",
    },
    activeCliTool: "none",
    alternative: "cc agent",
  };

  const { AgentRouter } = await import("../lib/agent-router.js");
  const config = agentOptions(options);
  const router = config.backends
    ? new AgentRouter({
        ...config,
        backends: config.backends.map((b) => ({
          ...b,
          installed: { claude, codex }[b.type]?.found ?? null,
        })),
      })
    : AgentRouter.autoDetect({ ...config, cliDetections: { claude, codex } });
  const backends = router.summary();

  if (options.json) {
    console.log(JSON.stringify({ ...status, backends }, null, 2));
    return;
  }

  console.log(chalk.bold.cyan("\n⚡ Orchestrator Status\n"));
  console.log(chalk.bold("  CLI Tools"));
  console.log(
    `    ${chalk.gray("claude:")}  ` +
      (claude.found ? chalk.green(claude.version) : chalk.red("not installed")),
  );
  console.log(
    `    ${chalk.gray("codex:")}   ` +
      (codex.found ? chalk.green(codex.version) : chalk.gray("not installed")),
  );
  console.log();
  console.log(chalk.bold("  Auto-detected Backends"));
  for (const b of backends) {
    const icon = b.kind === "cli" ? "🖥" : "🌐";
    console.log(
      `    ${icon} ${chalk.cyan(b.type.padEnd(12))} ${b.executionMode} — ${b.blockedReason}`,
    );
  }

  console.log(
    chalk.yellow(
      "  Installed/configured does not mean runnable. Use cc agent for tool execution.",
    ),
  );

  console.log();
  console.log(chalk.bold("  Notification Channels"));
  const { NotificationManager } = await import("../lib/notifiers/index.js");
  const nm = NotificationManager.fromEnv();
  const channels = nm.activeChannels;
  if (channels.length === 0) {
    console.log(
      chalk.gray(
        "    (none configured — set TELEGRAM_BOT_TOKEN, WECOM_WEBHOOK_URL, etc.)",
      ),
    );
  } else {
    for (const ch of channels) {
      console.log(`    ${chalk.green("✓")} ${ch}`);
    }
  }
  console.log();
}

// ─── Webhook mode (receive commands from IM platforms) ─────────────

async function _webhookMode(cwd, options, evolutionCompositionFactory = null) {
  const { createServer } = await import("http");
  const { parseDingTalkIncoming, parseFeishuIncoming, parseWeComIncoming } =
    await import("../lib/notifiers/index.js");
  const { Orchestrator } = await import("../lib/orchestrator.js");
  const { WebhookSecurityGate } = await import("../lib/webhook-security.js");

  const port = parseInt(options.webhookPort, 10) || 18820;

  const orch = new Orchestrator({
    cwd,
    agents: agentOptions(options),
    verbose: options.verbose,
    evolutionCompositionFactory,
  });
  const secretEnvironmentName =
    options.webhookSecretEnv || "CC_ORCHESTRATE_WEBHOOK_SECRET";
  if (!/^[A-Z_][A-Z0-9_]{0,127}$/u.test(secretEnvironmentName)) {
    throw new Error("--webhook-secret-env must be a valid environment name");
  }
  const webhookAuthMode = String(options.webhookAuthMode || "cc").toLowerCase();
  if (!new Set(["cc", "vendor"]).has(webhookAuthMode)) {
    throw new Error("--webhook-auth-mode must be cc or vendor");
  }
  const securityGate = new WebhookSecurityGate({
    authMode: webhookAuthMode,
    secret:
      webhookAuthMode === "cc" ? process.env[secretEnvironmentName] : undefined,
    vendorCredentials: {
      dingtalkSecret:
        process.env.CC_ORCHESTRATE_DINGTALK_SECRET ||
        process.env.DINGTALK_SECRET,
      feishuEncryptKey:
        process.env.CC_ORCHESTRATE_FEISHU_ENCRYPT_KEY ||
        process.env.FEISHU_ENCRYPT_KEY,
      wecomToken:
        process.env.CC_ORCHESTRATE_WECOM_TOKEN || process.env.WECOM_TOKEN,
      wecomEncodingAesKey:
        process.env.CC_ORCHESTRATE_WECOM_ENCODING_AES_KEY ||
        process.env.WECOM_ENCODING_AES_KEY,
      wecomReceiveId:
        process.env.CC_ORCHESTRATE_WECOM_RECEIVE_ID ||
        process.env.WECOM_RECEIVE_ID,
    },
    maxRequestsPerMinute: parseInt(options.webhookRateLimit, 10) || 30,
  });
  const maxBodyBytes = Math.max(
    1,
    parseInt(options.webhookMaxBodyBytes, 10) || 262144,
  );

  const server = createServer(async (req, res) => {
    const requestUrl = new URL(req.url || "/", "http://127.0.0.1");
    const url = requestUrl.pathname;
    const query = Object.fromEntries(requestUrl.searchParams.entries());
    const channel =
      url === "/wecom"
        ? "wecom"
        : url === "/dingtalk"
          ? "dingtalk"
          : url === "/feishu"
            ? "feishu"
            : null;
    if (!channel) {
      res.writeHead(404);
      res.end("Not Found");
      return;
    }
    if (
      req.method === "GET" &&
      channel === "wecom" &&
      webhookAuthMode === "vendor"
    ) {
      try {
        const verified = securityGate.verifyWeComUrl({
          query,
          remoteAddress: req.socket.remoteAddress || "unknown",
        });
        res.writeHead(200, { "Content-Type": "text/plain; charset=utf-8" });
        res.end(verified.echo);
      } catch (error) {
        if (error?.retryAfterSeconds) {
          res.setHeader("Retry-After", String(error.retryAfterSeconds));
        }
        res.writeHead(error?.statusCode || 401);
        res.end("Unauthorized");
      }
      return;
    }
    if (req.method !== "POST") {
      res.writeHead(405);
      res.end("Method Not Allowed");
      return;
    }
    if (Number(req.headers["content-length"] || 0) > maxBodyBytes) {
      res.writeHead(413);
      res.end("Payload Too Large");
      req.resume();
      return;
    }
    const bodyChunks = [];
    let bodyBytes = 0;
    let bodyRejected = false;
    req.on("data", (chunk) => {
      if (bodyRejected) return;
      bodyBytes += chunk.length;
      if (bodyBytes > maxBodyBytes) {
        bodyRejected = true;
        res.writeHead(413);
        res.end("Payload Too Large");
        return;
      }
      bodyChunks.push(chunk);
    });
    req.on("end", async () => {
      if (bodyRejected) return;
      // Decode once: per-chunk toString() would corrupt a multi-byte UTF-8
      // char (e.g. Chinese IM webhook text) split across a chunk boundary.
      let body = Buffer.concat(bodyChunks).toString("utf-8");
      let taskText = null;
      let source = `webhook:${channel}`;
      let verified;

      try {
        verified = securityGate.verify({
          channel,
          headers: req.headers,
          body,
          query,
          remoteAddress: req.socket.remoteAddress || "unknown",
        });
        body = verified.body;
      } catch (error) {
        if (error?.retryAfterSeconds) {
          res.setHeader("Retry-After", String(error.retryAfterSeconds));
        }
        res.writeHead(error?.statusCode || 401);
        res.end("Unauthorized");
        return;
      }

      try {
        if (url === "/wecom") {
          taskText = parseWeComIncoming(body);
        } else if (url === "/dingtalk") {
          const parsed = JSON.parse(body);
          taskText = parseDingTalkIncoming(parsed);
        } else if (url === "/feishu") {
          const parsed = JSON.parse(body);
          // Feishu challenge verification
          if (parsed.challenge) {
            res.writeHead(200, { "Content-Type": "application/json" });
            res.end(JSON.stringify({ challenge: parsed.challenge }));
            return;
          }
          taskText = parseFeishuIncoming(parsed);
        }
      } catch {
        res.writeHead(400);
        res.end("Bad Request");
        return;
      }

      if (!taskText) {
        res.writeHead(200, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ ok: true, message: "no task detected" }));
        return;
      }

      // Acknowledge immediately (IM platforms require fast response)
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(
        JSON.stringify({
          ok: true,
          message: `task queued: ${taskText.slice(0, 60)}`,
        }),
      );

      // Run orchestration async
      if (!options.json) {
        console.log(
          chalk.cyan(`[webhook] Received task: `) + taskText.slice(0, 80),
        );
      }
      orch
        .addTask(taskText, {
          source,
          cwd,
          dataPolicy: verified.dataPolicy,
          runCI: options.ci !== false,
          notify: true,
        })
        .catch((err) =>
          console.error(chalk.red(`[webhook] Error: ${err.message}`)),
        );
    });
  });

  server.listen(port, "127.0.0.1", () => {
    console.log(chalk.bold.cyan("\n⚡ Orchestrator Webhook Server\n"));
    console.log(
      `  ${chalk.gray("WeCom:")}    POST http://localhost:${port}/wecom`,
    );
    console.log(
      `  ${chalk.gray("DingTalk:")} POST http://localhost:${port}/dingtalk`,
    );
    console.log(
      `  ${chalk.gray("Feishu:")}   POST http://localhost:${port}/feishu`,
    );
    console.log(`  ${chalk.gray("Auth:")}     ${webhookAuthMode}`);
    console.log(chalk.gray("\n  Press Ctrl+C to stop\n"));
  });

  process.on("SIGINT", () => {
    server.close();
    orch.stopCronWatch();
    console.log(chalk.gray("\nWebhook server stopped."));
    process.exit(0);
  });
}

// ─── Watch mode ──────────────────────────────────────────────────

async function _watchMode(cwd, options, evolutionCompositionFactory = null) {
  const { Orchestrator } = await import("../lib/orchestrator.js");
  const intervalMs = parseInt(options.interval, 10) * 60_000 || 600_000;

  const orch = new Orchestrator({
    cwd,
    agents: agentOptions(options),
    verbose: options.verbose,
    evolutionCompositionFactory,
  });
  orch.startCronWatch(intervalMs);

  orch.on("cron:tick", ({ at }) => {
    if (!options.json) console.log(chalk.gray(`[cron] tick at ${at}`));
  });

  console.log(
    chalk.cyan(`\n⚡ Orchestrator watch mode started`) +
      chalk.gray(` (interval: ${options.interval}m)`),
  );
  console.log(chalk.gray("  Press Ctrl+C to stop\n"));

  // Keep alive
  process.on("SIGINT", () => {
    orch.stopCronWatch();
    console.log(chalk.gray("\nOrchestrator stopped."));
    process.exit(0);
  });
}

// ─── Summary printer ─────────────────────────────────────────────

function _printSummary(task) {
  console.log();
  console.log(chalk.bold("  Summary"));
  console.log(chalk.gray("  ─────────────────────────────────"));
  console.log(`  ID:       ${chalk.cyan(task.id)}`);
  console.log(`  Source:   ${task.source}`);
  console.log(`  Retries:  ${task.retries}`);
  console.log(`  Status:   ${_statusColor(task.status)}`);

  if (task.subtasks?.length) {
    console.log(`  Subtasks: ${task.subtasks.length}`);
  }

  if (task.agentResults?.length) {
    const passed = task.agentResults.filter((r) => r.success).length;
    console.log(
      `  Agents:   ${chalk.green(passed)} passed / ${chalk.red(task.agentResults.length - passed)} failed`,
    );
  }
  console.log();
}

function _statusColor(status) {
  const colors = {
    completed: chalk.green,
    "ci-passed": chalk.green,
    failed: chalk.red,
    "ci-failed": chalk.red,
    retrying: chalk.yellow,
    dispatched: chalk.cyan,
    "ci-checking": chalk.cyan,
  };
  return (colors[status] || chalk.white)(status);
}

