        { id: "s2", description: "subtask 2" },
      ],
      ciPasses: true,
    });
    const task = await orch.addTask("large task", { cwd: "/tmp" });
    expect(task.subtasks).toHaveLength(2);
    expect(bridgeDeps.spawn).toHaveBeenCalledTimes(2);
