// verify-06: paid pre-decomposition precheck.
//
// Guards the frozen implementation contract in
// packages/cli/src/lib/orchestrator.js#addTask (and its agent-router.js
// preflight): a rejected backend must terminate the task *before* notifications
// and before paid decomposition runs. This is an independent regression suite,
// distinct from packages/cli/__tests__/integration/orchestrator-workflow.test.js.
//
// The preflight is `this._router.assertDispatchAvailable?.()` at the top of
// addTask (orchestrator.js ~line 196). It passes iff at least one configured
// backend is non-CLI (api); if every backend is an external agent CLI it throws
// `{ code: "AGENT_ROUTER_EXTERNAL_MODEL_INGRESS_UNATTESTED" }`
// (agent-router.js ~line 550). The call precedes task registration, the
// notifyStart fire-and-forget, and `_decompose`.

import { describe, it, expect, vi } from "vitest";
import {
  Orchestrator,
  TASK_STATUS,
} from "../../src/lib/orchestrator.js";

describe("paid pre-decomposition precheck (verify-06)", () => {
  // ── Negative control: every backend is a rejected external CLI. ─────
  // Same construction as the positive control except the guard condition
  // (all backends isCLI) is flipped, so a different guard cannot be the
  // cause of the rejection. notifyStart and _decompose must stay zero and
  // no task may be registered.
  it("terminates before decomposition when every backend is rejected", async () => {
    const notifyStart = vi.fn();
    const orch = new Orchestrator({
      agents: { backends: [{ type: "claude" }, { type: "codex" }] },
      notifier: { isConfigured: true, notifyStart },
      evolutionCompositionFactory: null,
    });
    const decompose = vi.spyOn(orch, "_decompose");

    await expect(orch.addTask("fix this")).rejects.toMatchObject({
      code: "AGENT_ROUTER_EXTERNAL_MODEL_INGRESS_UNATTESTED",
    });

    expect(decompose).not.toHaveBeenCalled();
    expect(notifyStart).not.toHaveBeenCalled();
    expect(orch._tasks.size).toBe(0);
  });

  // ── Positive control: an admissible (api) backend passes the preflight. ──
  // Same construction as the negative control except one backend is non-CLI,
  // so the guard lets execution reach decomposition. _decompose is stubbed to
  // return a successful record so the test isolates "preflight admitted".
  it("reaches decomposition when an admissible backend exists", async () => {
    const notifyStart = vi.fn();
    const orch = new Orchestrator({
      agents: { backends: [{ type: "openai" }] },
      notifier: { isConfigured: true, notifyStart },
      evolutionCompositionFactory: null,
    });
    const decompose = vi.spyOn(orch, "_decompose").mockResolvedValue({
      subtasks: [],
      agentResults: [],
    });

    const task = await orch.addTask("fix this");

    expect(decompose).toHaveBeenCalledTimes(1);
    expect(task.status).toBe(TASK_STATUS.COMPLETED);
  });

  // ── Positive control for the notify side of the precheck. ────────────
  // Once the preflight admits, notifyStart is permitted to fire for a
  // configured notifier; the rejected case above proves it must not fire
  // when the backend is rejected. This keeps the notify prerequisite valid
  // (notifier configured, notify enabled) in the admitted path.
  it("allows the start notification only after the preflight admits", async () => {
    const notifyStart = vi.fn();
    const orch = new Orchestrator({
      agents: { backends: [{ type: "anthropic" }] },
      notifier: { isConfigured: true, notifyStart },
      evolutionCompositionFactory: null,
    });
    vi.spyOn(orch, "_decompose").mockResolvedValue({
      subtasks: [],
      agentResults: [],
    });

    await orch.addTask("fix this");

    expect(notifyStart).toHaveBeenCalledTimes(1);
  });
});

 * @param {number}   opts.priority    - 1 (high) – 3 (low)
 * @param {string}   opts.cwd        - Override project dir for this task
 * @param {string}   opts.context    - Extra context (e.g. stack trace from Sentry)
 * @param {boolean}  opts.runCI      - Whether to run CI after agents complete
 * @param {boolean}  opts.notify     - Whether to send Telegram notification
 * @returns {Promise<object>} Final task record
 */
async addTask(description, opts = {}) {
  assertCLILegacyMutationAllowed("Orchestrator.addTask");
  // Reject opaque external CLIs before notifications, Run creation or paid
  // decomposition. This preflight never replaces the dispatch ingress gate.
  this._router.assertDispatchAvailable?.();
  const task = {
    id: generateId("task"),
    description,
    source: opts.source || TASK_SOURCE.CLI,
    priority: opts.priority || 2,
    cwd: opts.cwd || this.cwd,
    context: opts.context || "",
    dataPolicy: opts.dataPolicy || null,
    runCI: opts.runCI !== false,
    notify: opts.notify !== false,
    status: TASK_STATUS.PENDING,
    subtasks: [],
    agentResults: [],
    retries: 0,
    ciErrors: [],
    createdAt: new Date().toISOString(),
    completedAt: null,
    runtimeClaims: ORCHESTRATOR_RUNTIME_CLAIMS,
    terminalEvidence: [],
  };

  this._tasks.set(task.id, task);
  this._pruneTasks();
  this.emit("task:added", task);

  if (this.notifier.isConfigured && task.notify) {
    // Fire-and-forget start notification
    this.notifier
      .notifyStart({
        taskId: task.id,
        description: task.description.slice(0, 100),
        subtaskCount: 1, // will update after decomposition
      })
      .catch(() => {});
  }

  let evolutionComposition = null;
  try {
    if (this._evolutionCompositionFactory !== null) {
      evolutionComposition = captureAgentEvolutionRuntimeComposition(
        await this._evolutionCompositionFactory(
          Object.freeze({
            mode: "orchestrate",
            runId: task.id,
            taskId: task.id,
            source: task.source,
            cwd: task.cwd,
          }),
        ),
      );
      if (
        evolutionComposition.runId !== task.id ||
        evolutionComposition.evolutionIngress.runId !== task.id ||
        evolutionComposition.evolutionIngress.tenantId !==
          evolutionComposition.tenantId
      ) {
        const error = new Error(
          "Orchestrator evolution composition is not bound to the requested Run",
        );
        error.code = "CC_AGENT_EVOLUTION_INGRESS_FAILED";
        throw error;
      }
      await evolutionComposition.evolutionIngress.start();
      await evolutionComposition.evolutionIngress.ingestUserPrompt({
        content: task.description,
        context: task.context,
        taskId: task.id,
        source: `orchestrate:${task.source}`,
      });
    }
  } catch (error) {
    task.status = TASK_STATUS.FAILED;
    task.error = error.message;
    this.emit("task:failed", { task, error });
    throw error;
  }

  await this._orchestrate(
    task,
    evolutionComposition?.evolutionIngress ?? null,
  );
  return task;
}

/**
 * Get current status of all tasks.
 */
status() {
  const tasks = [...this._tasks.values()].map((t) => ({
    id: t.id,
    description: t.description.slice(0, 80),
    status: t.status,
    source: t.source,
    retries: t.retries,
    createdAt: t.createdAt,
    runtimeClaims: t.runtimeClaims,
    terminalEvidence: t.terminalEvidence,
  }));

  return {
    tasks,
    pool: this._router.summary(),
    ciCommand: this.ciCommand,
    cronActive: this._cronTimer !== null,
  };
}

/**
 * Start a cron watch that periodically polls for new tasks from input sources.
 * @param {number} intervalMs - Poll interval (default 600_000 = 10 min)
 */
startCronWatch(intervalMs = 600_000) {
  assertCLILegacyMutationAllowed("Orchestrator.startCronWatch");
  if (this._cronTimer) return;
  this._log(`Cron watch started (every ${Math.round(intervalMs / 60_000)}m)`);
  this._cronTimer = setInterval(() => this._cronTick(), intervalMs);
}

stopCronWatch() {
  assertCLILegacyMutationAllowed("Orchestrator.stopCronWatch");
  if (this._cronTimer) {
    clearInterval(this._cronTimer);
    this._cronTimer = null;
  }
}

// ─── Orchestration pipeline ──────────────────────────────────────

async _orchestrate(task, evolutionIngress = null) {
  assertCLILegacyMutationAllowed("Orchestrator._orchestrate");
  try {
    // Step 1: Decompose
    task.subtasks = await this._decompose(task, evolutionIngress);
    task.status = TASK_STATUS.DISPATCHED;

    // Step 2: Dispatch to Claude Code agents
    task.agentResults = await this._dispatch(task, evolutionIngress);
    this._assertSuccessfulAgentResults(task);

    // Step 3: CI/CD check
    if (task.runCI) {
      await this._ciLoop(task, evolutionIngress);
    } else {
      await this._completeTask(task, evolutionIngress);
    }
  } catch (err) {
    task.status = TASK_STATUS.FAILED;
    task.error = err.message;
    this.emit("task:failed", { task, error: err });
    this._log(`Task ${task.id} failed: ${err.message}`);
  }
}

async _completeTask(task, evolutionIngress, ciResult = null) {
  assertCLILegacyMutationAllowed("Orchestrator._completeTask");
  task.status = TASK_STATUS.FINALIZING;
  if (evolutionIngress !== null) await evolutionIngress.complete();
  if (ciResult !== null && this.notifier.isConfigured && task.notify) {
    await this.notifier.notifySuccess({
      taskId: task.id,
      description: task.description.slice(0, 100),
      agentCount: task.subtasks.length,
      duration: Date.now() - new Date(task.createdAt).getTime(),
      filesChanged: ciResult.filesChanged || [],
    });
  }
  task.completedAt = new Date().toISOString();
  task.status = TASK_STATUS.COMPLETED;
  this.emit("task:complete", task);
}

/** LLM-driven task decomposition into coding subtasks. */
async _decompose(task, evolutionIngress = null) {
  assertCLILegacyMutationAllowed("Orchestrator._decompose");
  task.status = TASK_STATUS.DECOMPOSING;
  this.emit("task:decomposing", task);

  const systemPrompt =
    "You are a senior software architect. Given a coding task, break it into 1-4 " +
    "concrete, independently executable subtasks. Each subtask should be completable " +
    "by a single AI coding agent. Return ONLY a JSON array of objects with keys: " +
    '"id" (string), "description" (string), "context" (string, optional extra detail). ' +
    "No markdown, no explanation.";

  const userMsg =
    `Task: ${task.description}\n` +
    (task.context ? `\nAdditional context:\n${task.context}` : "");

  try {
    if (evolutionIngress === null) {
      const error = new Error(
        "Orchestrator model egress requires an authenticated evolution ingress",
      );
      error.code = "CC_AGENT_EVOLUTION_INGRESS_FAILED";
      throw error;
    }
    const chat = createChatFn({
      ...this._llmOptions,
      evolutionIngress,
    });
    const raw = await chat(
      [
        { role: "system", content: systemPrompt },
        { role: "user", content: userMsg },
      ],
      { maxTokens: 1024 },
    );

    const subtasks = JSON.parse(_extractJson(raw));
    if (!Array.isArray(subtasks) || subtasks.length === 0)
      throw new Error("empty");

    this.emit("task:decomposed", { task, subtasks });
    this._log(`Decomposed into ${subtasks.length} subtask(s)`);
    return subtasks;
  } catch (error) {
    if (isTerminalModelFailure(error)) throw error;
    // Fallback: treat whole task as single subtask
    const fallback = [
      { id: "sub-1", description: task.description, context: task.context },
    ];
    this.emit("task:decomposed", { task, subtasks: fallback });
    return fallback;
  }
}

/** Dispatch subtasks to the Claude Code pool. */
async _dispatch(task, evolutionIngress = null) {
  assertCLILegacyMutationAllowed("Orchestrator._dispatch");
  this.emit("agents:dispatched", { task, count: task.subtasks.length });
  this._log(
    `Dispatching ${task.subtasks.length} subtask(s) to ${this._router.summary().length} agent backend(s)`,
  );

  const results = await this._router.dispatch(task.subtasks, {
    cwd: task.cwd,
    ...(evolutionIngress === null ? {} : { evolutionIngress }),
  });
  this.emit("agents:complete", { task, results });

  return results;
}

/** Run CI command and retry loop. */
async _ciLoop(task, evolutionIngress = null) {
  assertCLILegacyMutationAllowed("Orchestrator._ciLoop");
  for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
    task.status = TASK_STATUS.CI_CHECKING;
    this.emit("ci:checking", { task, attempt });
    this._log(
      `Running CI (attempt ${attempt + 1}/${this.maxRetries + 1}): ${this.ciCommand}`,
    );

    const ciResult = this._runCI(task.cwd);

    if (ciResult.pass) {
      task.status = TASK_STATUS.CI_PASSED;
      this.emit("ci:pass", { task });
      this._log(`CI passed for task ${task.id}`);

      await this._completeTask(task, evolutionIngress, ciResult);
      return;
    }

    // CI failed
    task.status = TASK_STATUS.CI_FAILED;
    task.ciErrors = ciResult.errors;
    this.emit("ci:fail", { task, errors: ciResult.errors, attempt });
    this._log(
      `CI failed (attempt ${attempt + 1}): ${ciResult.errors.slice(0, 3).join("; ")}`,
    );

    if (this.notifier.isConfigured && task.notify) {
      await this.notifier.notifyFailure({
        taskId: task.id,
        description: task.description.slice(0, 100),
        errors: ciResult.errors,
        retryNumber: attempt + 1,
      });
    }

    if (attempt >= this.maxRetries) break;

    // Re-dispatch with error context
    task.status = TASK_STATUS.RETRYING;
    task.retries = attempt + 1;
    this.emit("task:retrying", { task, attempt: attempt + 1 });

    const fixSubtasks = task.subtasks.map((st) => ({
      ...st,
      id: `${st.id}-retry${attempt + 1}`,
      context:
        `Previous attempt failed CI. Fix the following errors:\n${ciResult.errors.slice(0, 5).join("\n")}\n\n` +
        `Original task: ${st.description}`,
    }));

    task.agentResults = await this._router.dispatch(fixSubtasks, {
      cwd: task.cwd,
      ...(evolutionIngress === null ? {} : { evolutionIngress }),
    });
    this._assertSuccessfulAgentResults(task);
    this.emit("agents:complete", { task, results: task.agentResults });
  }

  // Exhausted retries
  task.status = TASK_STATUS.FAILED;
  task.completedAt = new Date().toISOString();
  task.error = `CI failed after ${this.maxRetries} retries`;
  this.emit("task:failed", { task, error: task.error });
}

